"use server";

import { z } from "zod";
import { redirect } from "next/navigation";
import { refresh, updateTag } from "next/cache";
import type { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { requireAdmin } from "@/lib/auth";
import { audit } from "@/lib/audit";
import { TAGS } from "@/lib/tags";
import { razorpay } from "@/lib/razorpay";
import { after } from "next/server";
import { sendShippingUpdate } from "@/lib/email";
import { rupeesToPaise } from "@/lib/money";
import { slugify } from "@/lib/utils";
import { checkbox, productSchema } from "@/lib/validators";

export type ActionState = { ok?: boolean; error?: string; fieldErrors?: Record<string, string[] | undefined> } | undefined;

async function requireOwner() {
  const user = await requireAdmin();
  if (user.role !== "ADMIN") throw new Error("Only the store owner can do this.");
  return user;
}

// Media URLs must point at our own upload route — never arbitrary external URLs.
const mediaUrl = z.string().regex(/^\/media\/(products|gallery|banners|categories)\/[a-f0-9]{24}\.(webp|mp4|webm)$|^\/media\/(products|gallery|banners|categories)\/(seed|demo)-[a-z0-9-]+\.webp$/);

/* ───────────────────────── Products ───────────────────────── */

export async function saveProduct(_: ActionState, formData: FormData): Promise<ActionState> {
  const admin = await requireAdmin();
  const id = String(formData.get("id") || "");
  const parsed = productSchema.safeParse(Object.fromEntries(formData));
  if (!parsed.success) return { fieldErrors: parsed.error.flatten().fieldErrors, error: "Please fix the highlighted fields." };
  const d = parsed.data;

  let images: { url: string; alt: string }[];
  let specs: { label: string; value: string }[];
  try {
    images = z.array(z.object({ url: mediaUrl, alt: z.string().max(160) })).max(12).parse(JSON.parse(String(formData.get("images") || "[]")));
    specs = z.array(z.object({ label: z.string().trim().min(1).max(60), value: z.string().trim().min(1).max(200) })).max(40).parse(JSON.parse(d.specs || "[]"));
  } catch {
    return { error: "Invalid images or specifications." };
  }
  if (rupeesToPaise(d.mrp) < rupeesToPaise(d.price)) return { fieldErrors: { mrp: ["MRP must be ≥ selling price"] } };

  const slug = slugify(d.slug || d.name);
  const clash = await db.product.findFirst({ where: { OR: [{ slug }, { sku: d.sku }], NOT: id ? { id } : undefined }, select: { slug: true, sku: true } });
  if (clash) return { fieldErrors: clash.sku === d.sku ? { sku: ["SKU already used"] } : { slug: ["URL slug already used"] } };

  const data = {
    name: d.name,
    slug,
    sku: d.sku,
    brand: d.brand || null,
    material: d.material || null,
    categoryId: d.categoryId,
    shortDescription: d.shortDescription || null,
    description: d.description,
    price: rupeesToPaise(d.price),
    mrp: rupeesToPaise(d.mrp),
    costPrice: d.costPrice !== undefined && String(formData.get("costPrice")) !== "" ? rupeesToPaise(d.costPrice) : null,
    gstRate: d.gstRate,
    hsnCode: d.hsnCode || null,
    stock: d.stock,
    lowStockThreshold: d.lowStockThreshold,
    weightGrams: d.weightGrams ?? null,
    warranty: d.warranty || null,
    tags: (d.tags ?? "").split(",").map((t) => t.trim().toLowerCase()).filter(Boolean).slice(0, 20),
    specs,
    isActive: d.isActive,
    isFeatured: d.isFeatured,
    emiEligible: d.emiEligible,
    engravingAvailable: d.engravingAvailable,
  };

  const previous = id ? await db.product.findUnique({ where: { id }, select: { slug: true } }) : null;
  const product = await db.$transaction(async (tx) => {
    const p = id ? await tx.product.update({ where: { id }, data }) : await tx.product.create({ data });
    await tx.productImage.deleteMany({ where: { productId: p.id } });
    if (images.length) await tx.productImage.createMany({ data: images.map((img, i) => ({ productId: p.id, url: img.url, alt: img.alt || p.name, sortOrder: i })) });
    return p;
  });

  await audit(admin.id, id ? "product.update" : "product.create", "Product", product.id, { name: product.name, price: product.price, stock: product.stock });
  // Instantly refresh every storefront view that shows products.
  updateTag(TAGS.products);
  updateTag(TAGS.product(product.slug));
  if (previous && previous.slug !== product.slug) updateTag(TAGS.product(previous.slug));
  redirect(`/admin/products?saved=${encodeURIComponent(product.name)}`);
}

export async function quickUpdateProduct(id: string, patch: { stock?: number; price?: number; isActive?: boolean; isFeatured?: boolean }) {
  const admin = await requireAdmin();
  const data: Prisma.ProductUpdateInput = {};
  if (patch.stock !== undefined) data.stock = Math.max(0, Math.floor(patch.stock));
  if (patch.price !== undefined && patch.price > 0) data.price = rupeesToPaise(patch.price);
  if (patch.isActive !== undefined) data.isActive = patch.isActive;
  if (patch.isFeatured !== undefined) data.isFeatured = patch.isFeatured;
  const p = await db.product.update({ where: { id }, data });
  await audit(admin.id, "product.quick_update", "Product", id, patch);
  updateTag(TAGS.products);
  updateTag(TAGS.product(p.slug));
  refresh();
}

export async function deleteProduct(id: string) {
  const admin = await requireAdmin();
  const p = await db.product.findUniqueOrThrow({ where: { id }, include: { _count: { select: { orderItems: true } } } });
  if (p._count.orderItems > 0) {
    // Keep order history intact: archive instead of hard delete.
    await db.product.update({ where: { id }, data: { isActive: false } });
    await audit(admin.id, "product.archive", "Product", id, { name: p.name });
  } else {
    await db.product.delete({ where: { id } });
    await audit(admin.id, "product.delete", "Product", id, { name: p.name });
  }
  updateTag(TAGS.products);
  updateTag(TAGS.product(p.slug));
  refresh();
}

/* ───────────────────────── Categories ───────────────────────── */

const categorySchema = z.object({
  id: z.string().optional(),
  name: z.string().trim().min(2).max(80),
  description: z.string().trim().max(300).optional(),
  parentId: z.string().optional(),
  sortOrder: z.coerce.number().int().min(0).max(999).default(0),
  isActive: checkbox,
});

export async function saveCategory(_: ActionState, formData: FormData): Promise<ActionState> {
  const admin = await requireAdmin();
  const parsed = categorySchema.safeParse(Object.fromEntries(formData));
  if (!parsed.success) return { error: "Category name is required (2–80 characters)." };
  const { id, parentId, ...rest } = parsed.data;
  const slug = slugify(rest.name);
  const clash = await db.category.findFirst({ where: { slug, NOT: id ? { id } : undefined } });
  if (clash) return { error: "A category with this name already exists." };
  if (id && parentId === id) return { error: "A category cannot be its own parent." };
  const data = { ...rest, slug, description: rest.description || null, parentId: parentId || null };
  const c = id ? await db.category.update({ where: { id }, data }) : await db.category.create({ data });
  await audit(admin.id, id ? "category.update" : "category.create", "Category", c.id, { name: c.name });
  updateTag(TAGS.categories);
  refresh();
  return { ok: true };
}

export async function deleteCategory(id: string): Promise<ActionState> {
  const admin = await requireAdmin();
  const count = await db.product.count({ where: { categoryId: id } });
  if (count) return { error: `Move or delete the ${count} products in this category first.` };
  await db.category.delete({ where: { id } });
  await audit(admin.id, "category.delete", "Category", id);
  updateTag(TAGS.categories);
  refresh();
  return { ok: true };
}

/* ───────────────────────── Orders ───────────────────────── */

const orderUpdateSchema = z.object({
  id: z.string(),
  status: z.enum(["PAID", "PROCESSING", "SHIPPED", "DELIVERED", "CANCELLED"]),
  courier: z.string().trim().max(60).optional(),
  trackingNumber: z.string().trim().max(80).optional(),
  note: z.string().trim().max(500).optional(),
});

export async function updateOrder(_: ActionState, formData: FormData): Promise<ActionState> {
  const admin = await requireAdmin();
  const parsed = orderUpdateSchema.safeParse(Object.fromEntries(formData));
  if (!parsed.success) return { error: "Invalid update." };
  const { id, status, courier, trackingNumber, note } = parsed.data;
  const order = await db.order.findUniqueOrThrow({ where: { id }, include: { items: true } });
  if (!order.paidAt && status !== "CANCELLED") return { error: "This order has not been paid yet." };

  await db.$transaction(async (tx) => {
    // Return stock when a paid order is cancelled.
    if (status === "CANCELLED" && order.status !== "CANCELLED" && order.stockCommitted) {
      for (const it of order.items) if (it.productId) await tx.product.update({ where: { id: it.productId }, data: { stock: { increment: it.quantity } } });
    }
    await tx.order.update({
      where: { id },
      data: {
        status,
        courier: courier || order.courier,
        trackingNumber: trackingNumber || order.trackingNumber,
        stockCommitted: status === "CANCELLED" ? false : order.stockCommitted,
        events: { create: { status, note: note || (trackingNumber ? `Tracking: ${courier ?? ""} ${trackingNumber}` : `Status set by ${admin.name}`) } },
      },
    });
  });
  await audit(admin.id, "order.status", "Order", id, { from: order.status, to: status });
  if (status !== order.status && (status === "SHIPPED" || status === "DELIVERED")) after(() => sendShippingUpdate(id));
  if (status === "CANCELLED") updateTag(TAGS.products);
  refresh();
  return { ok: true };
}

export async function refundOrder(_: ActionState, formData: FormData): Promise<ActionState> {
  let admin;
  try {
    admin = await requireOwner();
  } catch (e) {
    return { error: (e as Error).message };
  }
  const id = String(formData.get("id"));
  const rupees = Number(formData.get("amount"));
  const order = await db.order.findUniqueOrThrow({ where: { id } });
  if (!order.razorpayPaymentId) return { error: "No captured payment to refund." };
  const amount = Number.isFinite(rupees) && rupees > 0 ? Math.min(rupeesToPaise(rupees), order.total) : order.total;
  try {
    const refund = await razorpay().payments.refund(order.razorpayPaymentId, { amount, notes: { orderNumber: order.orderNumber, by: admin.email } });
    await db.order.update({
      where: { id },
      data: { status: amount >= order.total ? "REFUNDED" : order.status, events: { create: { status: "REFUND_INITIATED", note: `₹${amount / 100} refund ${refund.id}` } } },
    });
    await audit(admin.id, "order.refund", "Order", id, { amount, refundId: refund.id });
  } catch (e) {
    const msg = (e as { error?: { description?: string } }).error?.description ?? (e as Error).message;
    return { error: `Razorpay refund failed: ${msg}` };
  }
  refresh();
  return { ok: true };
}

/* ───────────────────────── Leads ───────────────────────── */

export async function updateLead(id: string, status: "NEW" | "CONTACTED" | "QUOTED" | "WON" | "LOST", adminNote?: string) {
  const admin = await requireAdmin();
  await db.lead.update({ where: { id }, data: { status, ...(adminNote !== undefined ? { adminNote: adminNote.slice(0, 1000) } : {}) } });
  await audit(admin.id, "lead.update", "Lead", id, { status });
  refresh();
}

