const gallerySchema = z.object({
  title: z.string().trim().min(2).max(120),
  description: z.string().trim().max(300).optional(),
  category: z.enum(["ENGRAVING", "B2B_PROJECT", "STORE"]),
  url: mediaUrl,
});

export async function createGalleryItem(input: z.input<typeof gallerySchema>): Promise<ActionState> {
  const admin = await requireAdmin();
  const parsed = gallerySchema.safeParse(input);
  if (!parsed.success) return { error: "Title and an uploaded file are required." };
  const mediaType = /\.(mp4|webm)$/.test(parsed.data.url) ? "VIDEO" : "IMAGE";
  const g = await db.galleryItem.create({ data: { ...parsed.data, description: parsed.data.description || null, mediaType } });
  await audit(admin.id, "gallery.create", "GalleryItem", g.id, { title: g.title });
  updateTag(TAGS.gallery);
  refresh();
  return { ok: true };
}

