/* ───────────────────────── Coupons ───────────────────────── */

const couponSchema = z.object({
  code: z.string().trim().toUpperCase().regex(/^[A-Z0-9_-]{3,30}$/, "Use 3–30 letters/numbers"),
  description: z.string().trim().max(160).optional(),
  type: z.enum(["PERCENT", "FLAT"]),
  value: z.coerce.number().positive(),
  minOrder: z.coerce.number().min(0).default(0),
  maxDiscount: z.coerce.number().min(0).optional(),
  usageLimit: z.coerce.number().int().min(1).optional(),
  validTo: z.string().optional(),
});

export async function createCoupon(_: ActionState, formData: FormData): Promise<ActionState> {
  const admin = await requireAdmin();
  const raw = Object.fromEntries([...formData].filter(([, v]) => v !== ""));
  const parsed = couponSchema.safeParse(raw);
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid coupon" };
  const c = parsed.data;
  if (c.type === "PERCENT" && c.value > 90) return { error: "Percentage cannot exceed 90%." };
  if (await db.coupon.findUnique({ where: { code: c.code } })) return { error: "Code already exists." };
  const created = await db.coupon.create({
    data: {
      code: c.code,
      description: c.description || null,
      type: c.type,
      value: c.type === "PERCENT" ? Math.round(c.value) : rupeesToPaise(c.value),
      minOrderAmount: rupeesToPaise(c.minOrder),
      maxDiscount: c.maxDiscount ? rupeesToPaise(c.maxDiscount) : null,
      usageLimit: c.usageLimit ?? null,
      validTo: c.validTo ? new Date(`${c.validTo}T23:59:59+05:30`) : null,
    },
  });
  await audit(admin.id, "coupon.create", "Coupon", created.id, { code: c.code });
  refresh();
  return { ok: true };
}

export async function toggleCoupon(id: string, isActive: boolean) {
  const admin = await requireAdmin();
  await db.coupon.update({ where: { id }, data: { isActive } });
  await audit(admin.id, "coupon.toggle", "Coupon", id, { isActive });
  refresh();
}

/* ───────────────────────── Settings & staff ───────────────────────── */

export async function saveSettings(_: ActionState, formData: FormData): Promise<ActionState> {
  let admin;
  try {
    admin = await requireOwner();
  } catch (e) {
    return { error: (e as Error).message };
  }
  const announcement = String(formData.get("announcement") ?? "").trim().slice(0, 240);
  await db.siteSetting.upsert({ where: { key: "announcement" }, create: { key: "announcement", value: announcement }, update: { value: announcement } });
  await audit(admin.id, "settings.update", "SiteSetting", "announcement", { announcement });
  updateTag(TAGS.settings);
  refresh();
  return { ok: true };
}

export async function setUserRole(_: ActionState, formData: FormData): Promise<ActionState> {
  let admin;
  try {
    admin = await requireOwner();
  } catch (e) {
    return { error: (e as Error).message };
  }
  const email = String(formData.get("email") ?? "").trim().toLowerCase();
  const role = z.enum(["CUSTOMER", "STAFF", "ADMIN"]).safeParse(formData.get("role"));
  if (!role.success) return { error: "Invalid role" };
  const user = await db.user.findUnique({ where: { email } });
  if (!user) return { error: "No account with that email. Ask them to register first." };
  if (user.id === admin.id) return { error: "You cannot change your own role." };
  await db.user.update({ where: { id: user.id }, data: { role: role.data } });
  // Force re-login so the new permissions apply immediately.
  await db.session.deleteMany({ where: { userId: user.id } });
  await audit(admin.id, "user.role", "User", user.id, { email, role: role.data });
  refresh();
  return { ok: true };
}
